mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region that holds the state bucket."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that stores Terraform state. Bucket names are global, so pick one specific to your organization."
}

variable "state_access_principal_arns" {
  type        = list(string)
  description = "IAM principal ARNs allowed to read and write state. All other principals are denied by the bucket policy, so include the identity that runs this configuration."

  validation {
    condition     = length(var.state_access_principal_arns) > 0
    error_message = "At least one principal ARN is required, otherwise the bucket policy denies everyone."
  }
}

variable "noncurrent_version_retention_days" {
  type        = number
  description = "Days a superseded state version is kept before it is deleted. Older versions are the rollback path for a corrupt state."
  default     = 90
}
EOF
cat > main.tf <<'EOF'
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state" {
  statement {
    sid       = "DenyInsecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyPrincipalsOutsideAllowList"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "ArnNotEquals"
      variable = "aws:PrincipalArn"
      values   = var.state_access_principal_arns
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket, for the bucket argument of the s3 backend block."
  value       = aws_s3_bucket.state.id
}
EOF
cd ..
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  # Bucket is created by bootstrap/. Replace the placeholder name with the value of
  # `terraform output state_bucket_name` from that configuration. Credentials come from the
  # default AWS credential chain, never from this file.
  backend "s3" {
    bucket       = "example-org-reports-tfstate"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
printf '*.tfstate\n*.tfstate.*\n.terraform/\n*.tfplan\ntfplan\n*.tfvars\n' > .gitignore
terraform fmt -recursive -check -diff; terraform init -backend=false -input=false 2>&1 | tail -3; terraform validate; (cd bootstrap && terraform init -backend=false -input=false 2>&1 | tail -3; terraform validate); ls -a . bootstrap

