  description = "Name of the state bucket, for the bucket argument of the s3 backend block."
  value       = aws_s3_bucket.state.id
}
EOF
cd ..
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  # Bucket is created by bootstrap/. Replace the placeholder name with the value of
  # `terraform output state_bucket_name` from that configuration. Credentials come from the
  # default AWS credential chain, never from this file.
  backend "s3" {
    bucket       = "example-org-reports-tfstate"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true
  }

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
printf '*.tfstate\n*.tfstate.*\n.terraform/\n*.tfplan\ntfplan\n*.tfvars\n' > .gitignore
terraform fmt -recursive -check -diff; terraform init -backend=false -input=false 2>&1 | tail -3; terraform validate; (cd bootstrap && terraform init -backend=false -input=false 2>&1 | tail -3; terraform validate); ls -a . bootstrap
